// План specs/billing.md 3.3 (#2185f2, реджект Р1). Pre-Prod, preprod-a, EN, телефон 412. Только чтение.
// Manage Billing / Cancel subscription / Keep my plan — ПОД таблицей подписки, в экране без горизонтальной прокрутки
// (раньше были в колонке Actions за правым краем, x=471–603). Факты 17.11: кнопка видна под таблицей на 412.
// Присутствует либо «Cancel subscription», либо «Keep my plan» (зависит от состояния подписки) — проверяется та, что есть.
import { test, expect } from '../../fixtures';
import { SUB_ROLE, cancelSubscriptionButton, openBillingDirect } from './billing-helpers';

test.describe('Billing — buttons on a phone (#2185f2)', () => {
  test('Manage Billing and Cancel subscription / Keep my plan sit below the subscription table, inside the screen width #2185f2 @mobile', async ({ asUser }) => {
    const page = await asUser(SUB_ROLE);
    await openBillingDirect(page);

    const action = cancelSubscriptionButton(page).or(cancelSubscriptionButton(page, 'Keep my plan')).first();
    await expect(action).toBeVisible();
    await action.scrollIntoViewIfNeeded();

    const viewport = page.viewportSize();
    expect(viewport, 'размер окна телефона известен').not.toBeNull();
    const box = (await action.boundingBox())!;
    expect(box.x, 'кнопка не уходит за левый край').toBeGreaterThanOrEqual(0);
    expect(box.x + box.width, 'кнопка целиком в ширине экрана (без горизонтальной прокрутки)').toBeLessThanOrEqual(viewport!.width + 1);

    // Ниже таблицы подписки
    const table = page.getByRole('table').first();
    const tableBox = (await table.boundingBox())!;
    expect(box.y, 'кнопка под таблицей подписки').toBeGreaterThanOrEqual(tableBox.y + tableBox.height - 2);

    // Manage Billing — рядом, тоже в экране
    const manage = page.getByRole('button', { name: 'Manage Billing', exact: true }).or(page.getByRole('link', { name: 'Manage Billing', exact: true })).first();
    await expect(manage).toBeVisible();
    const mbox = (await manage.boundingBox())!;
    expect(mbox.x + mbox.width, 'Manage Billing в ширине экрана').toBeLessThanOrEqual(viewport!.width + 1);

    // Страница не прокручивается вбок
    const overflow = await page.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth);
    expect(overflow, 'нет горизонтальной прокрутки страницы').toBeLessThanOrEqual(1);
  });
});
